                                        <span className="max-w-[140px] shrink-0 truncate text-right text-[11px] text-slate-400">{quemMovimento(m)}</span>
                                    </li>
                                ))}
                            </ul>
                        )
                    )}
                </div>
            </div>
        </div>
    );
}

